#include <stdio.h>
#include <string.h>

// Function to reverse a null-terminated string in-place
void reverse_string_in_place(char *str) {
    int len = strlen(str);
    int start = 0;
    int end = len - 1;

    // Swap characters from the start and end of the string
    while (start < end) {
        char temp = str[start];
        str[start] = str[end];
        str[end] = temp;
        start++;
        end--;
    }
}

